consumers.className:
{cn(
                      "h-7 px-2 text-[10px] rounded-full transition-all",
                      value.monitoramentoItens?.includes(item)
                        ? "bg-emerald-600 text-white border-emerald-600 hover:bg-emerald-700"
                        : "bg-background border-emerald-200 text-emerald-700 hover:bg-emerald-50"
                    )}

{cn(
                        "flex-1 h-8 text-[10px] px-1",
                        value.monitoramentoFrequencia === dias
                          ? "bg-emerald-100 border-emerald-400 text-emerald-800"
                          : "bg-background"
                      )}

{cn(
                      "h-8 px-3 text-xs rounded-full transition-all",
                      value.retornoMotivo === motivo
                        ? "bg-primary text-primary-foreground border-primary"
                        : "bg-background border-primary/20 text-primary/70 hover:bg-primary/5"
                    )}

{cn(
                "w-full h-12 text-base font-bold shadow-lg active:scale-[0.98] transition-transform",
                value.proximoPasso === "emitir_recomendacao" 
                  ? "bg-primary text-primary-foreground shadow-primary/20" 
                  : "bg-primary text-primary-foreground shadow-primary/20"
              )}

{cn(
                      "h-7 px-2 text-[10px] rounded-full transition-all",
                      state.monitoramentoItens?.includes(item)
                        ? "bg-emerald-600 text-white border-emerald-600"
                        : "bg-background border-emerald-200 text-emerald-700"
                    )}

{cn(
                "h-7 w-7",
                isPaused ? "text-green-600 border-green-200 bg-green-50 hover:bg-green-100" : "text-amber-600 border-amber-200 bg-amber-50 hover:bg-amber-100"
              )}

{cn(
                        "flex-1 h-9 text-xs font-semibold border-2 transition-all",
                        "border-amber-200 hover:bg-amber-50",
                        form.tipo_item === "produto" && "bg-amber-100 text-amber-700 border-amber-500"
                      )}

{cn(
                        "flex-1 h-9 text-xs font-semibold border-2 transition-all",
                        "border-emerald-200 hover:bg-emerald-50",
                        form.tipo_item === "microrganismo" && "bg-emerald-100 text-emerald-700 border-emerald-500"
                      )}

{cn(
                    "h-9 text-[10px] sm:text-xs font-medium border transition-all",
                    tipoVisita === tipo.val 
                      ? "border-primary bg-primary/10 text-primary shadow-sm" 
                      : "hover:bg-accent/50"
                  )}

{cn(
          "h-8 w-full bg-background shadow-none focus-visible:ring-2 focus-visible:ring-sidebar-ring",
          className,
        )}
